// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Put must not revert for any admissible deposit amount");
    }
}
